SELECT 
FROM map_place_cache
WHERE provider = #{provider} AND provider_place_id = #{providerPlaceId}

SELECT FROM map_place_cache WHERE picked_count > 0 AND (name_normalized LIKE '%' || #{query} || '%' OR name_normalized % #{query})
AND sqrt(power((latitude - #{latitude}) * 111.32, 2) + power((longitude - #{longitude}) * 111.32 * cos(radians(#{latitude})), 2)) <= #{radiusKm}
ORDER BY (name_normalized LIKE #{query} || '%') DESC, similarity(name_normalized, #{query}) DESC, picked_count DESC LIMIT #{limit}

